-- ds_escalation — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_escalation.
-- Every breach on the latest scheduled run, escalated or held. Triage: Held back counter.

SELECT x.run_id, x.run_ts, x.rule_id, x.severity, x.violation_count, x.rows_scanned,
       x.cde_id, e.cde_name, e.business_domain, x.element_score_pct, x.element_target_pct,
       x.escalates, x.held_reason,
       CASE WHEN x.escalates THEN 0 ELSE 1 END                                  AS is_held
FROM   sdpt_data_trnf.udp_brnz.dq_results_v_check_escalation x
LEFT JOIN sdpt_data_trnf.udp_brnz.dq_config_v_cde_registry_current e ON e.cde_id = x.cde_id
WHERE  x.run_id = (SELECT run_id FROM sdpt_data_trnf.udp_brnz.dq_results_v_scheduled_run WHERE is_latest)
